const tierPrices: Record<Tier, number> = { Essential: 1050, Balanced: 1600, Complete: 2200 };
const tiers: Tier[] = ['Essential', 'Balanced', 'Complete'];
const API_BASE_URL = process.env.EXPO_PUBLIC_API_URL || 'http://localhost:3001';
Notifications.setNotificationHandler({ handleNotification: async () => ({ shouldShowBanner: true, shouldShowList: true, shouldPlaySound: true, shouldSetBadge: false }) });
async function registerPushToken() {
  if (Platform.OS === 'web' || !Device.isDevice) return null;
  const existing = await Notifications.getPermissionsAsync();
  let status = existing.status;
  if (status !== 'granted') status = (await Notifications.requestPermissionsAsync()).status;
  if (status !== 'granted') return null;
  const projectId = Constants.expoConfig?.extra?.eas?.projectId;
  const token = (await Notifications.getExpoPushTokenAsync(projectId ? { projectId } : undefined)).data;
  await fetch(`${API_BASE_URL}/api/devices/register`, { method: 'POST', headers: { 'Content-Type': 'application/json' }, body: JSON.stringify({ token, platform: Platform.OS, deviceName: Device.deviceName || 'Forward device' }) });
  return token;
}


