  if (submitted) return <View style={styles.infoCard}><Text style={styles.sectionTitle}>{mode === 'start' ? 'Claim started' : 'Claim found'}</Text><Text style={styles.body}>{mode === 'start' ? 'Your claim report is ready for review. A support agent will contact you.' : `We found ${reference.trim().toUpperCase()}. Status updates will appear here after the claims service is connected.`}</Text><Text style={styles.fit}>{mode === 'start' ? `Reference: ${submittedReference || 'pending'}` : 'Status: review pending'}</Text><Pressable style={styles.primary} onPress={onBack}><Text style={styles.primaryText}>Back to Claims</Text></Pressable></View>;
  return <View><View style={styles.quoteHeader}><Pressable onPress={onBack}><Text style={styles.back}>‹</Text></Pressable><Text style={styles.quoteLabel}>{mode === 'start' ? 'Start a claim' : 'Track a claim'}</Text><Text style={styles.progress}>Forward</Text></View><Text style={styles.sectionTitle}>{mode === 'start' ? 'Tell us what happened.' : 'Find your claim.'}</Text>{mode === 'start' ? <><Field label="Incident date" value={date} onChangeText={setDate} placeholder="YYYY-MM-DD" error={errors.date} /><Field label="Incident location" value={location} onChangeText={setLocation} placeholder="City or landmark" error={errors.location} /><Field label="What happened?" value={description} onChangeText={setDescription} placeholder="Describe the accident or damage" multiline error={errors.description} /></> : <Field label="Claim reference" value={reference} onChangeText={setReference} placeholder="FWD-CLM-2026" error={errors.reference} /> }{apiError && <Text style={styles.errorText}>{apiError}</Text>}<Pressable style={styles.primary} onPress={submit} disabled={saving}><Text style={styles.primaryText}>{saving ? 'Saving…' : mode === 'start' ? 'Submit claim report' : 'Track claim'}  →</Text></Pressable><Pressable style={styles.secondary} onPress={onHelp}><Text style={styles.secondaryText}>Need roadside or urgent help?</Text></Pressable></View>;
